components.css:
.c-x-faq{padding:var(--c-pad);border-bottom:var(--c-bw) solid var(--c-line)}
.c-x-faq h2{font-family:var(--c-fd);font-weight:var(--c-hw);letter-spacing:var(--c-tt);font-size:24px;margin-bottom:14px}
.c-x-faq details{border-top:1px solid var(--c-line);padding:12px 0}
.c-x-faq summary{cursor:pointer;font-weight:600}
.c-x-faq p{color:var(--c-mut);margin-top:6px;line-height:1.6}
